function decode_cursor(?string $cursor): ?array {
    if ($cursor === null || $cursor === '') {
        return [];
    }

    $raw = base64_decode($cursor, true);

    if ($raw === false) {
        return null;
    }

    $decoded = json_decode($raw, true);

    return is_array($decoded) ? $decoded : null;
}

tasks.test_suite:
expect('null cursor means first page', decode_cursor(null), null);
expect('empty cursor means no next page', decode_cursor(''), null);
expect('decodes a well-formed cursor', decode_cursor(base64_encode(json_encode(['id' => 42, 'sort' => 7]))), ['id' => 42, 'sort' => 7]);
expect('invalid base64 returns null', decode_cursor('!!!not-base64!!!'), null);
expect('base64 of non-JSON returns null', decode_cursor('aGVsbG8='), null);

